const log = [];

function hold(name) {
  log.push("+" + name);
  return {
    [Symbol.dispose]() {
      log.push("-" + name);
    },
  };
}

function inner() {
  using b = hold("b");
  using c = hold("c");
  return log.length;
}

function outer() {
  using a = hold("a");
  log.push(inner());
  return log.length;
}

console.log(outer());
console.log(log.join(" "));
